function cheapestSplit(costs: number[][]): number {
  const total = costs.length, half = total / 2;
  let best = new Array(half + 1).fill(Infinity);
  best[0] = 0;
  for (let i = 0; i < total; i++) {
    const [a, b] = costs[i];
    const next = new Array(half + 1).fill(Infinity);
    for (let j = 0; j <= Math.min(i, half); j++) {
      if (best[j] === Infinity) continue;
      if (i - j < half) next[j] = Math.min(next[j], best[j] + b); // to B
      if (j < half) next[j + 1] = Math.min(next[j + 1], best[j] + a); // to A
    }
    best = next;
  }
  return best[half];
}

