class Solution:
    def cheapestSplit(self, costs: List[List[int]]) -> int:
        half = len(costs) // 2
        INF = float("inf")
        best = [0] + [INF] * half
        for i, (a, b) in enumerate(costs):
            nxt = [INF] * (half + 1)
            for j in range(min(i, half) + 1):
                if best[j] == INF:
                    continue
                if i - j < half:
                    nxt[j] = min(nxt[j], best[j] + b)
                if j < half:
                    nxt[j + 1] = min(nxt[j + 1], best[j] + a)
            best = nxt
        return best[half]

