function cheapestSplit(costs: number[][]): number {
  const sorted = [...costs].sort((p, q) => (p[0] - p[1]) - (q[0] - q[1]));
  const half = sorted.length / 2;
  let total = 0;
  for (let i = 0; i < sorted.length; i++) total += i < half ? sorted[i][0] : sorted[i][1];
  return total;
}

