class Solution:
    def cheapestSplit(self, costs: List[List[int]]) -> int:
        ordered = sorted(costs, key=lambda c: c[0] - c[1])
        half = len(ordered) // 2
        return sum(a for a, _ in ordered[:half]) + sum(b for _, b in ordered[half:])

